const apiBaseUrl = String(globalThis.__POHADATA_CONFIG__?.apiBaseUrl || "").replace(/\/+$/, "");
function apiFetch(path, options = {}) { const route = path.startsWith("/") ? path : `/${path}`; return fetch(`${apiBaseUrl}${route}`, { credentials: "include", ...options }); }

const evidenceTypes = [
  { id: 'traditional', label: 'Uso tradicional / etnobotánico', short: 'Tradicional', color: 'terracotta', description: 'Registro cultural o etnobotánico.' },
  { id: 'phytochemical', label: 'Evidencia fitoquímica', short: 'Fitoquímica', color: 'violet', description: 'Compuestos caracterizados en la planta.' },
  { id: 'in-vitro', label: 'Estudios in vitro', short: 'In vitro', color: 'blue', description: 'Ensayos de laboratorio fuera de un organismo vivo.' },
  { id: 'animal', label: 'Estudios en animales', short: 'Animales', color: 'amber', description: 'Modelos animales preclínicos.' },
  { id: 'human', label: 'Estudios en humanos', short: 'Humanos', color: 'green', description: 'Investigación con participantes humanos.' },
];

const icons = {
  grid: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>',
  leaf: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.4 3.6C13.1 3.8 6.5 5.1 4.1 10.2c-1.6 3.3-.2 6.5 2.5 7.6 2.8 1.1 6.1-.1 7.4-2.9 1-2.1.6-4.2-.9-5.8 1.2-.2 2.7-.1 4.4.4-1.2 2.1-1.3 4.4-.3 6.8M6.1 20.4c1.1-4.1 3.8-7 7.9-8.5"/></svg>',
  search: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg>',
  arrow: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5m6 6-6-6 6-6"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',
  sliders: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16M8 4v4M16 10v4M10 16v4"/></svg>',
  scale: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v16M6 20h12M4 8h16M7 8l-3 6h6L7 8Zm10 0-3 6h6l-3-6Z"/></svg>',
  beaker: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 3h6M10 3v6l-5.5 9.2A1.8 1.8 0 0 0 6 21h12a1.8 1.8 0 0 0 1.5-2.8L14 9V3M8 15h8"/></svg>',
  info: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 10v6M12 7h.01"/></svg>',
  menu: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg>',
  chevron: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>',
  external: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 4h6v6M20 4l-9 9M18 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h5"/></svg>',
};

const state = { plants: [], loading: true, error: '', route: getRoute(), search: '', filter: 'Todas', sort: 'A–Z', compare: [], mixture: [], compareOpen: false, mobileMenu: false, admin: false, editor: null, adminSearch: '' };

function getRoute() {
  const parts = window.location.hash.replace(/^#\/?/, '').split('/').filter(Boolean);
  return { page: parts[0] || 'home', id: parts[1] || '', sub: parts[2] || '' };
}
function navigate(path) { window.location.hash = `#/${path}`; state.route = getRoute(); state.mobileMenu = false; render(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
window.addEventListener('hashchange', () => { state.route = getRoute(); render(); });
function icon(name, className = '') { return `<span class="icon ${className}">${icons[name] || ''}</span>`; }
function escapeHtml(value) { return String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[char])); }
function getPlant(id) { return state.plants.find((plant) => plant.id === id || plant.slug === id); }
function evidence(id) { return evidenceTypes.find((item) => item.id === id) || evidenceTypes[0]; }
function evidenceBadge(id, compact = false) { const item = evidence(id); return `<span class="evidence-badge ${item.color} ${compact ? 'compact' : ''}"><span class="evidence-dot"></span>${compact ? item.short : item.label}</span>`; }
function unavailable() { return '<span class="unavailable">Información no disponible actualmente.</span>'; }
function button(label, action, cls = 'button secondary', iconName = '') { return `<button class="${cls}" data-action="${action}">${iconName ? icon(iconName) : ''}${label}</button>`; }
function plantVisual(plant, size = 'medium') { const initials = (plant.commonName || '?').split(/\s+/).map((word) => word[0]).join('').slice(0, 2).toUpperCase(); return `<div class="plant-visual ${size} ${escapeHtml(plant.visualColor || 'green')}">${plant.image?.url ? `<img src="${escapeHtml(plant.image.url)}" alt="${escapeHtml(plant.image.caption || plant.commonName)}"/>` : `${icon('leaf', 'visual-leaf')}<span class="visual-initials">${escapeHtml(initials)}</span>`}</div>`; }

function shell(content) {
  const page = state.route.page;
  const nav = [['home', 'Resumen', 'grid'], ['plants', 'Explorar plantas', 'leaf'], ['categories', 'Categorías y propiedades', 'sliders'], ['compare', 'Comparar plantas', 'scale'], ['mixture', 'Constructor de mezclas', 'beaker']];
  return `<div class="app-shell"><aside class="sidebar ${state.mobileMenu ? 'open' : ''}"><div class="brand" data-action="navigate:home"><span class="brand-mark">${icon('leaf')}</span><div><div class="brand-name">Pohã<span>Data</span></div><div class="brand-subtitle">Conocimiento botánico</div></div></div><div class="sidebar-label">Espacio de trabajo</div><nav class="nav-list">${nav.map(([id, label, ico]) => `<button class="nav-item ${page === id ? 'active' : ''}" data-action="navigate:${id}">${icon(ico)}<span>${label}</span>${id === 'plants' ? `<em>${state.plants.length || '—'}</em>` : ''}</button>`).join('')}</nav><div class="sidebar-spacer"></div><div class="method-card">${icon('info', 'method-icon')}<div><strong>Marco de evidencia</strong><p>Tradición, fitoquímica y experimentación permanecen diferenciadas.</p><button data-action="navigate:about">Leer metodología ${icon('arrow')}</button></div></div><div class="sidebar-footer"><span class="status-dot"></span><span>Datos PostgreSQL</span><span class="version">v1.0</span></div></aside><div class="main-area"><header class="topbar"><button class="mobile-menu" data-action="toggle-menu">${icon('menu')}</button><div class="breadcrumbs"><span>PohãData</span><span>/</span><strong>${pageTitle(page)}</strong></div><div class="topbar-actions"><span class="data-status">${icon('beaker')} PostgreSQL</span><button class="icon-button" title="Metodología" data-action="navigate:about">${icon('info')}</button></div></header><main>${content}</main><footer class="site-footer"><div><span class="footer-brand">PohãData</span><span>Recurso educativo y de investigación sobre plantas de Paraguay</span></div><div class="footer-links"><button data-action="navigate:about">Acerca de PohãData ${icon('arrow')}</button><button data-action="navigate:admin">Administración</button></div></footer></div></div>`;
}
function pageTitle(page) { return ({ home: 'Resumen', plants: 'Explorar plantas', plant: 'Perfil de planta', categories: 'Categorías y propiedades', compare: 'Comparar plantas', mixture: 'Constructor de mezclas', about: 'Acerca de PohãData', admin: 'Administración' }[page] || 'Resumen'); }
function sectionIntro(eyebrow, title, text, actions = '') { return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></div><div class="intro-actions">${actions}</div></div>`; }

function homePage() {
  const featured = getPlant('yerba-mate') || state.plants[0];
  return `<div class="home-page"><section class="hero-section"><div class="hero-copy"><div class="eyebrow pill-eyebrow"><span class="eyebrow-dot"></span> Paraguay · plataforma botánica</div><h1>Donde la tradición<br/><em>encuentra evidencia.</em></h1><p class="hero-lede">PohãData conecta las plantas presentes en hogares paraguayos, mate y tereré con la literatura científica disponible sobre ellas — un perfil transparente a la vez.</p><div class="hero-actions">${button('Explorar el catálogo', 'navigate:plants', 'button primary', 'arrow')} ${button('Cómo funciona', 'navigate:about', 'button text-button')}</div><div class="hero-note">${icon('info')} <span>Educativo y orientado a la investigación. No ofrece diagnósticos, recetas ni recomendaciones de tratamiento.</span></div></div><div class="hero-art"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-center">${icon('leaf')}<span>${state.plants.length || '—'}</span><small>perfiles botánicos</small></div><div class="art-label label-top">tradición<br/><strong>documentada</strong></div><div class="art-label label-bottom">conectada con<br/><strong>evidencia</strong></div></div></section><section class="stat-strip"><div><strong>${state.plants.length}</strong><span>perfiles en la base</span></div><div><strong>5</strong><span>categorías de evidencia</span></div><div><strong>${new Set(state.plants.flatMap((plant) => plant.compounds.map((item) => item.name))).size}</strong><span>grupos fitoquímicos</span></div><div class="stat-message"><span class="stat-line"></span><span>Diseñado para crecer con la literatura</span>${icon('arrow')}</div></section><section class="home-grid"><div class="section-heading"><div><div class="eyebrow">Comienza a explorar</div><h2>Conocimiento, por capas</h2></div><button class="link-button" data-action="navigate:plants">Ver todas las plantas ${icon('arrow')}</button></div><div class="explore-tiles"><button class="explore-tile tile-plants" data-action="navigate:plants"><span class="tile-icon">${icon('leaf')}</span><span class="tile-title">Explorar plantas</span><span>Busca por nombre, uso, compuesto o evidencia.</span>${icon('arrow')}</button><button class="explore-tile tile-categories" data-action="navigate:categories"><span class="tile-icon">${icon('sliders')}</span><span class="tile-title">Buscar por propiedad</span><span>Distingue lo tradicional, experimental y fitoquímico.</span>${icon('arrow')}</button><button class="explore-tile tile-compare" data-action="navigate:compare"><span class="tile-icon">${icon('scale')}</span><span class="tile-title">Comparar lado a lado</span><span>Comprende diferencias sin clasificar plantas.</span>${icon('arrow')}</button><button class="explore-tile tile-mixture" data-action="navigate:mixture"><span class="tile-icon">${icon('beaker')}</span><span class="tile-title">Construir una mezcla</span><span>Mapea características compartidas con lenguaje neutral.</span>${icon('arrow')}</button></div></section><section class="evidence-preview"><div class="evidence-preview-copy"><div class="eyebrow">Marco de evidencia</div><h2>Cada afirmación tiene un contexto.</h2><p>PohãData no combina distintos tipos de conocimiento en una sola etiqueta de “comprobado”. Cada perfil hace visible el origen de la información.</p><button class="link-button" data-action="navigate:about">Leer la metodología ${icon('arrow')}</button></div><div class="evidence-stack">${evidenceTypes.map((item) => `<div class="evidence-row ${item.color}">${evidenceBadge(item.id)}<span>${item.description}</span><span class="row-arrow">${icon('arrow')}</span></div>`).join('')}</div></section>${featured ? `<section class="featured-section"><div class="section-heading"><div><div class="eyebrow">Perfil destacado</div><h2>Un punto de partida</h2></div><button class="link-button" data-action="navigate:plant:${featured.slug}">Abrir perfil ${icon('arrow')}</button></div><div class="featured-card">${plantVisual(featured, 'large')}<div class="featured-info"><div class="plant-kicker">${escapeHtml(featured.family)} · ${escapeHtml(featured.parts.join(' · '))}</div><h3>${escapeHtml(featured.commonName)}</h3><div class="guarani-name">${escapeHtml(featured.guaraniName)}</div><p>${escapeHtml(featured.description)}</p><div class="badge-row">${featured.evidenceTypes.slice(0, 4).map((id) => evidenceBadge(id, true)).join('')}</div></div><div class="featured-meta"><span>Nombre científico</span><strong>${escapeHtml(featured.scientificName)}</strong><span>Actividad reportada</span><strong>${escapeHtml(featured.activities[0]?.name || 'No registrada')}</strong></div></div></section>` : ''}</div>`;
}

function plantCard(plant) { return `<article class="plant-card"> <button class="card-image-button" data-action="navigate:plant:${plant.slug}">${plantVisual(plant)}<span class="card-open">${icon('arrow')}</span></button><div class="plant-card-body"><div class="plant-kicker">${escapeHtml(plant.family)} · ${escapeHtml(plant.parts.join(' · '))}</div><h3><button data-action="navigate:plant:${plant.slug}">${escapeHtml(plant.commonName)}</button></h3><div class="guarani-name">${escapeHtml(plant.guaraniName || 'Nombre guaraní no registrado')}</div><div class="scientific-name">${escapeHtml(plant.scientificName)}</div><div class="card-footer"><span>${escapeHtml(plant.categories[0] || 'Sin categoría')}</span><span>${plant.evidenceTypes.length} capas de evidencia</span></div></div></article>`; }
function plantsPage() {
  let shown = [...state.plants]; const query = state.search.toLowerCase();
  if (query) shown = shown.filter((plant) => [plant.commonName, plant.guaraniName, plant.scientificName, plant.family, plant.description, ...plant.categories, ...plant.compounds.map((item) => item.name), ...plant.activities.map((item) => item.name)].join(' ').toLowerCase().includes(query));
  if (state.filter !== 'Todas') shown = shown.filter((plant) => plant.categories.includes(state.filter) || plant.preparations.some((item) => item.name === state.filter) || plant.evidenceTypes.includes(state.filter));
  shown.sort((a, b) => state.sort === 'A–Z' ? a.commonName.localeCompare(b.commonName) : b.evidenceTypes.length - a.evidenceTypes.length);
  const filters = [...new Set(['Todas', ...state.plants.flatMap((plant) => plant.categories), ...state.plants.flatMap((plant) => plant.preparations.map((item) => item.name)), ...evidenceTypes.map((item) => item.id)])];
  return `<div class="content-page catalog-page">${sectionIntro('Catálogo de plantas', 'Explora el índice vivo.', 'Comienza por un nombre, una categoría tradicional o una capa de evidencia. El catálogo está conectado a PostgreSQL y puede crecer con la investigación.', button('Construir una mezcla', 'navigate:mixture', 'button secondary', 'beaker'))}<div class="catalog-toolbar"><label class="search-box">${icon('search')}<input data-field="search" value="${escapeHtml(state.search)}" placeholder="Buscar por nombre común, guaraní o científico…"/></label><div class="toolbar-selects"><label>Filtrar por<select data-field="filter">${filters.map((option) => `<option value="${escapeHtml(option)}" ${option === state.filter ? 'selected' : ''}>${escapeHtml(evidenceTypes.find((item) => item.id === option)?.label || option)}</option>`).join('')}</select></label><label>Ordenar<select data-field="sort"><option ${state.sort === 'A–Z' ? 'selected' : ''}>A–Z</option><option ${state.sort === 'Capas de evidencia' ? 'selected' : ''}>Capas de evidencia</option></select></label></div></div><div class="catalog-summary"><span><strong>${shown.length}</strong> de ${state.plants.length} plantas</span><span class="summary-spacer"></span><span class="legend-label">Capas de evidencia</span>${evidenceTypes.slice(0, 4).map((item) => evidenceBadge(item.id, true)).join('')}</div><div class="plant-grid">${shown.length ? shown.map(plantCard).join('') : `<div class="empty-state"><div>${icon('search')}</div><h3>No hay plantas que coincidan</h3><p>Prueba otro nombre o restablece el filtro.</p><button class="button secondary" data-action="reset-catalog">Restablecer catálogo</button></div>`}</div></div>`;
}

function evidencePanel(plant) { return `<div class="evidence-panel"><div class="panel-title"><div><div class="eyebrow">Mapa de evidencia</div><h2>¿Qué tipo de información está disponible?</h2></div>${icon('info')}</div><p class="panel-intro">Las capas muestran el tipo de fuente. Más capas no significan que una planta sea “mejor” ni clínicamente efectiva.</p><div class="evidence-list">${evidenceTypes.map((item) => `<div class="evidence-item ${plant.evidenceTypes.includes(item.id) ? 'present' : 'muted'}"><div class="evidence-item-main">${evidenceBadge(item.id)}<span class="evidence-status">${plant.evidenceTypes.includes(item.id) ? 'Disponible' : 'No registrada'}</span></div>${plant.evidence.filter((entry) => entry.evidenceType === item.id).map((entry) => `<p>${escapeHtml(entry.notes || item.description)}</p>`).join('')}</div>`).join('')}</div></div>`; }
function plantPage(id) {
  const plant = getPlant(id); if (!plant) return `<div class="content-page"><div class="empty-state"><h3>Planta no encontrada</h3>${button('Volver al catálogo', 'navigate:plants', 'button secondary')}</div></div>`;
  const related = state.plants.filter((item) => item.id !== plant.id && item.categories.some((category) => plant.categories.includes(category))).slice(0, 3);
  return `<div class="content-page plant-profile-page"><button class="back-link" data-action="navigate:plants">${icon('back')} Volver al catálogo</button><section class="profile-hero"><div class="profile-hero-visual">${plantVisual(plant, 'profile')}</div><div class="profile-hero-copy"><div class="eyebrow">Perfil de planta · ${escapeHtml(plant.family)}</div><h1>${escapeHtml(plant.commonName)}</h1><div class="profile-alias">${escapeHtml(plant.guaraniName || 'Nombre guaraní no registrado')}</div><p class="scientific-large">${escapeHtml(plant.scientificName)}</p><p class="profile-summary">${escapeHtml(plant.description || unavailable())}</p><div class="badge-row">${plant.evidenceTypes.map((id) => evidenceBadge(id, true)).join('')}</div></div><div class="profile-actions">${button('Añadir a comparación', `add-compare:${plant.id}`, 'button secondary', 'scale')}${button('Añadir a mezcla', `add-mixture:${plant.id}`, 'button primary', 'plus')}</div></section><div class="profile-disclaimer">${icon('info')} <span><strong>Cómo leer este perfil:</strong> el uso tradicional, la caracterización fitoquímica y los hallazgos experimentales son tipos distintos de información. Nada aquí constituye diagnóstico, receta ni recomendación de tratamiento.</span></div><div class="profile-layout"><div class="profile-main"><section class="info-section"><div class="section-label"><span>01</span><div><div class="eyebrow">Identificación</div><h2>Conoce la planta</h2></div></div><div class="fact-grid"><div><span>Nombre común</span><strong>${escapeHtml(plant.commonName)}</strong></div><div><span>Nombre en guaraní</span><strong>${escapeHtml(plant.guaraniName || unavailable())}</strong></div><div><span>Nombre científico</span><strong class="serif">${escapeHtml(plant.scientificName)}</strong></div><div><span>Familia botánica</span><strong>${escapeHtml(plant.family || unavailable())}</strong></div><div><span>Partes utilizadas</span><strong>${escapeHtml(plant.parts.join(' · ') || unavailable())}</strong></div><div><span>Sinónimos</span><strong>${escapeHtml(plant.synonyms.join(' · ') || unavailable())}</strong></div></div></section><section class="info-section"><div class="section-label"><span>02</span><div><div class="eyebrow">Usos tradicionales</div><h2>Cómo aparece en la práctica</h2></div></div>${plant.traditionalUses.length ? plant.traditionalUses.map((use) => `<div class="traditional-card traditional-card-stack"><div class="quote-mark">“</div><div><strong>${escapeHtml(use.category)}</strong><p>${escapeHtml(use.description)}</p><div class="traditional-tags">${[use.plantPart, use.preparation].filter(Boolean).map((item) => `<span>${escapeHtml(item)}</span>`).join('')}</div>${use.contextNotes ? `<small>${escapeHtml(use.contextNotes)}</small>` : ''}</div></div>`).join('') : unavailable()}<p class="section-footnote">Esta sección informa contexto tradicional y etnobotánico. No implica que un uso esté médicamente probado.</p></section><section class="info-section"><div class="section-label"><span>03</span><div><div class="eyebrow">Preparación</div><h2>Formas documentadas</h2></div></div><div class="preparation-list">${plant.preparations.length ? plant.preparations.map((item) => `<div><strong>${escapeHtml(item.name)}</strong>${item.notes ? `<span>${escapeHtml(item.notes)}</span>` : ''}</div>`).join('') : unavailable()}</div><p class="section-footnote">PohãData no ofrece recomendaciones de dosis ni instrucciones médicas.</p></section><section class="info-section"><div class="section-label"><span>04</span><div><div class="eyebrow">Fitoquímica</div><h2>Compuestos reportados</h2></div></div><div class="compound-grid">${plant.compounds.length ? plant.compounds.map((compound, index) => `<div class="compound-card"><span class="compound-number">${String(index + 1).padStart(2, '0')}</span><strong>${escapeHtml(compound.name)}</strong><span>${escapeHtml(compound.compoundClass || 'Grupo de compuestos')}</span>${compound.notes ? `<p>${escapeHtml(compound.notes)}</p>` : ''}${compound.quantitativeValues.length ? `<div class="quantity-list">${compound.quantitativeValues.map((item) => `<small>${escapeHtml([item.value || [item.minimumValue, item.maximumValue].filter(Boolean).join('–')].filter(Boolean).join(' ') || 'Valor registrado')} ${escapeHtml(item.unit)} · ${escapeHtml(item.basis)}</small>`).join('')}</div>` : ''}</div>`).join('') : unavailable()}</div><div class="shared-callout">${icon('info')} <span>La presencia y cantidad pueden variar según parte de la planta, preparación, origen y condiciones de cosecha. Los valores solo aparecen cuando se registraron en la base.</span></div></section><section class="info-section"><div class="section-label"><span>05</span><div><div class="eyebrow">Actividades biológicas reportadas</div><h2>Señales de investigación</h2></div></div><div class="activity-list">${plant.activities.length ? plant.activities.map((item) => `<div><strong>${escapeHtml(item.name)}</strong><p>${escapeHtml(item.description || '')}</p></div>`).join('') : unavailable()}</div></section><section class="info-section"><div class="section-label"><span>06</span><div><div class="eyebrow">Referencias científicas</div><h2>Fuentes asociadas</h2></div></div><div class="references-list">${plant.references.length ? plant.references.map((reference, i) => `<div class="reference-row"><span>${String(i + 1).padStart(2, '0')}</span><p>${escapeHtml(reference.citationText || [reference.authors, reference.title, reference.journalOrSource, reference.publicationYear].filter(Boolean).join(' — '))}${reference.doi ? ` <small>DOI: ${escapeHtml(reference.doi)}</small>` : ''}</p>${reference.url ? `<a href="${escapeHtml(reference.url)}" target="_blank" rel="noreferrer">${icon('external')}</a>` : ''}</div>`).join('') : unavailable()}</div></section></div><aside class="profile-aside">${evidencePanel(plant)}${related.length ? `<div class="related-card"><div class="eyebrow">Explorar más</div><h3>Perfiles relacionados</h3><div class="related-plants">${related.map((item) => `<button data-action="navigate:plant:${item.slug}">${plantVisual(item, 'tiny')}<span><strong>${escapeHtml(item.commonName)}</strong><small>${escapeHtml(item.categories[0])}</small></span>${icon('chevron')}</button>`).join('')}</div></div>` : ''}</aside></div></div>`;
}

function categoriesPage() { const categories = [...new Set(state.plants.flatMap((plant) => plant.categories))].map((label) => ({ label, plants: state.plants.filter((plant) => plant.categories.includes(label)) })); return `<div class="content-page categories-page">${sectionIntro('Mapa de propiedades', 'Encuentra un patrón, no una promesa.', 'Explora los perfiles a través del lenguaje de los registros tradicionales, la fitoquímica y la investigación experimental.') }<div class="category-grid">${categories.map((category, index) => `<button class="category-card ${['terracotta', 'violet', 'blue', 'green', 'teal', 'amber'][index % 6]}" data-action="category:${escapeHtml(category.label)}"><div class="category-card-top"><span class="category-symbol">${icon(index % 2 ? 'beaker' : 'leaf')}</span><span class="category-type">Propiedad documentada</span></div><h3>${escapeHtml(category.label)}</h3><p>Presente en registros de ${category.plants.length} perfil${category.plants.length === 1 ? '' : 'es'}.</p><div class="category-card-bottom"><span><strong>${category.plants.length}</strong> perfiles</span>${icon('arrow')}</div></button>`).join('')}</div><div class="category-note">${icon('info')}<div><strong>¿Por qué indicar el tipo?</strong><p>Una categoría tradicional describe cómo se usa o entiende una planta en un contexto cultural. Una categoría experimental describe observaciones de laboratorio o preclínicas. No son intercambiables.</p></div></div></div>`; }
function comparePage() { const selected = state.compare.map(getPlant).filter(Boolean); return `<div class="content-page compare-page">${sectionIntro('Lectura comparativa', 'Comparar sin clasificar.', 'Selecciona de dos a cuatro plantas para observar cómo difieren sus usos, compuestos y capas de evidencia. La comparación es descriptiva, no una recomendación.') }<div class="compare-picker"><div class="picker-heading"><div><span class="eyebrow">Tu selección</span><strong>${selected.length} de 4 plantas seleccionadas</strong></div><button class="link-button" data-action="clear-compare">Borrar todo</button></div><div class="picker-chips">${selected.map((plant) => `<button class="selection-chip" data-action="remove-compare:${plant.id}">${plantVisual(plant, 'micro')}<span>${escapeHtml(plant.commonName)}</span>${icon('plus')}</button>`).join('')}${selected.length < 4 ? `<button class="add-chip" data-action="open-compare-picker">${icon('plus')} Añadir planta</button>` : ''}</div><div class="compare-select-wrap ${state.compareOpen ? 'open' : ''}"><label>Añadir una planta<select data-field="add-compare"><option value="">Elegir un perfil…</option>${state.plants.filter((plant) => !state.compare.includes(plant.id)).map((plant) => `<option value="${plant.id}">${escapeHtml(plant.commonName)} · ${escapeHtml(plant.guaraniName)}</option>`).join('')}</select></label></div></div>${selected.length >= 2 ? `<div class="comparison-table-wrap"><table class="comparison-table"><thead><tr><th>Señal</th>${selected.map((plant) => `<th><div class="table-plant-heading">${plantVisual(plant, 'micro')}<div><strong>${escapeHtml(plant.commonName)}</strong><span>${escapeHtml(plant.guaraniName)}</span></div></div></th>`).join('')}</tr></thead><tbody>${comparisonRow('Uso tradicional', selected.map((plant) => plant.traditionalUses.map((item) => item.description).join(' ') || unavailable()))}${comparisonRow('Partes utilizadas', selected.map((plant) => plant.parts.join(' · ') || unavailable()))}${comparisonRow('Preparación', selected.map((plant) => plant.preparations.map((item) => item.name).join(' · ') || unavailable()))}${comparisonRow('Compuestos reportados', selected.map((plant) => plant.compounds.map((item) => item.name).join(' · ') || unavailable()))}${comparisonRow('Actividades biológicas', selected.map((plant) => plant.activities.map((item) => item.name).join(' · ') || unavailable()))}${comparisonRow('Capas de evidencia', selected.map((plant) => `<div class="table-badges">${plant.evidenceTypes.map((id) => evidenceBadge(id, true)).join('') || unavailable()}</div>`))}</tbody></table></div><div class="comparison-footnote">${icon('info')} Las diferencias en disponibilidad de evidencia no son una clasificación de valor o eficacia.</div>` : `<div class="empty-state compare-empty"><div>${icon('scale')}</div><h3>Selecciona al menos dos plantas</h3><p>Elige perfiles arriba para crear una vista lado a lado.</p></div>`}</div>`; }
function comparisonRow(label, values) { return `<tr><th>${label}</th>${values.map((value) => `<td class="text-row">${value}</td>`).join('')}</tr>`; }
function mixturePage() { const included = state.mixture.map((item) => ({ ...item, plant: getPlant(item.id) })).filter((item) => item.plant); const compounds = [...new Set(included.flatMap(({ plant }) => plant.compounds.map((item) => item.name)))]; const activities = [...new Set(included.flatMap(({ plant }) => plant.activities.map((item) => item.name)))]; const categories = [...new Set(included.flatMap(({ plant }) => plant.categories))]; return `<div class="content-page mixture-page">${sectionIntro('Espacio informativo', 'Construye un perfil de mezcla.', 'Selecciona plantas y añade cantidades de muestra opcionales para observar características documentadas que se superponen. Esta herramienta no estima dosis, seguridad ni efectos médicos.') }<div class="mixture-layout"><section class="mixture-builder card-surface"><div class="builder-head"><div><div class="eyebrow">1 · Elegir plantas</div><h2>¿Qué contiene la mezcla?</h2></div><span class="sample-tag">Cantidades de muestra</span></div><div class="mixture-rows">${included.map(({ plant, amount }) => `<div class="mixture-row">${plantVisual(plant, 'micro')}<div class="mixture-row-name"><strong>${escapeHtml(plant.commonName)}</strong><span>${escapeHtml(plant.guaraniName)}</span></div><label><span>Cantidad</span><input type="number" min="0" max="99" value="${amount}" data-amount="${plant.id}"/><small>unidades de muestra</small></label><button class="remove-button" data-action="remove-mixture:${plant.id}" title="Quitar planta">×</button></div>`).join('')}</div><div class="add-plant-row"><select data-field="add-mixture"><option value="">Añadir otra planta…</option>${state.plants.filter((plant) => !state.mixture.some((item) => item.id === plant.id)).map((plant) => `<option value="${plant.id}">${escapeHtml(plant.commonName)} · ${escapeHtml(plant.guaraniName)}</option>`).join('')}</select>${icon('plus')}</div><div class="builder-note">${icon('info')} <span>Las cantidades son datos de muestra. No se usan para calcular dosis o concentraciones médicamente significativas.</span></div></section><aside class="mixture-result card-surface"><div class="builder-head"><div><div class="eyebrow">2 · Leer el mapa</div><h2>Perfil de mezcla</h2></div><span class="result-count">${included.length} plantas</span></div><div class="result-summary"><div class="summary-ring"><strong>${compounds.length}</strong><span>grupos<br/>fitoquímicos</span></div><p>La mezcla contiene <strong>${included.length} plantas</strong> con ${activities.length ? `${activities.length} señales de actividad reportada` : 'ninguna señal de actividad mapeada'}.</p></div><div class="result-section"><span class="result-label">Categorías tradicionales</span><div class="result-tags">${categories.map((category) => `<span>${escapeHtml(category)}</span>`).join('') || unavailable()}</div></div><div class="result-section"><span class="result-label">Principales grupos fitoquímicos</span><div class="compound-bars">${compounds.slice(0, 6).map((compound) => { const count = included.filter(({ plant }) => plant.compounds.some((item) => item.name === compound)).length; return `<div class="compound-bar"><span>${escapeHtml(compound)}</span><span class="bar-track"><i style="width:${Math.max(22, count / Math.max(included.length, 1) * 100)}%"></i></span><small>${count}/${included.length}</small></div>`; }).join('') || unavailable()}</div></div><div class="evidence-summary">${icon('info')} <span>Combinar señales no crea un nuevo nivel de evidencia.</span></div></aside></div></div>`; }
function aboutPage() { return `<div class="content-page about-page">${sectionIntro('Acerca de PohãData', 'Un puente cuidadoso entre sistemas de conocimiento.', 'PohãData es un proyecto académico y tecnológico sobre plantas tradicionalmente utilizadas en Paraguay, especialmente en tereré, mate, tés, infusiones y preparaciones caseras.') }<div class="about-hero"><div class="about-hero-mark">${icon('leaf')}</div><div><div class="eyebrow">Nuestro norte</div><h2>Hacer visible la relación entre una planta, una afirmación y su fuente.</h2><p>Respetamos el conocimiento tradicional sin convertirlo en una promesa clínica, y hacemos legible la evidencia científica sin presentarla como más concluyente de lo que es.</p></div></div><div class="methodology-grid"><section class="methodology-section"><div class="method-number">01</div><div><div class="eyebrow">El propósito</div><h2>Un recurso público orientado a la investigación</h2><p>La plataforma organiza identidad, nombres locales, prácticas tradicionales, fitoquímica y señales bibliográficas en un mismo lugar comprensible.</p></div></section><section class="methodology-section"><div class="method-number">02</div><div><div class="eyebrow">La separación</div><h2>Los tipos de evidencia permanecen diferenciados</h2><p>El uso tradicional describe un registro cultural. La fitoquímica describe compuestos caracterizados. Los estudios in vitro y en animales describen observaciones experimentales. Los estudios en humanos describen investigación con personas. Ninguno se convierte silenciosamente en “tratamiento comprobado”.</p><div class="about-evidence-list">${evidenceTypes.map((item) => `<div>${evidenceBadge(item.id)}<span>${item.description}</span></div>`).join('')}</div></div></section><section class="methodology-section"><div class="method-number">03</div><div><div class="eyebrow">La futura capa de cálculo</div><h2>Datos cuantitativos solo cuando la fuente los respalda</h2><p>Las futuras mezclas usarán concentraciones documentadas, partes de la planta, condiciones de preparación y unidades compatibles. Cuando la literatura no respalde un valor fiable, PohãData mostrará que no está disponible.</p></div></section><section class="methodology-section"><div class="method-number">04</div><div><div class="eyebrow">El límite</div><h2>Lo que PohãData no hace</h2><p>La plataforma no diagnostica, receta, recomienda tratamientos, valida mezclas ni estima dosis médicamente significativas.</p><div class="boundary-list"><span>✓ Sin diagnósticos ni recetas</span><span>✓ Sin ranking de “mejor planta”</span><span>✓ Sin valores cuantitativos inventados</span><span>✓ Sin afirmaciones clínicas desde actividad de laboratorio</span></div></div></section></div></div>`; }

function adminLogin() { return `<div class="content-page admin-page admin-login"><div class="admin-login-card"><div class="brand-mark">${icon('leaf')}</div><div class="eyebrow">Área restringida</div><h1>Administración</h1><p>Ingresa la contraseña compartida para gestionar los perfiles de PohãData.</p><form data-admin-login><label>Contraseña<input name="password" type="password" autocomplete="current-password" required autofocus/></label><button class="button primary" type="submit">Iniciar sesión</button><p class="form-message" data-form-message></p></form><button class="back-link" data-action="navigate:home">${icon('back')} Volver a la aplicación</button></div></div>`; }
function input(label, name, value = '', type = 'text', required = false) { return `<label>${label}${required ? ' *' : ''}<input name="${name}" type="${type}" value="${escapeHtml(value)}" ${required ? 'required' : ''}/></label>`; }
function textarea(label, name, value = '') { return `<label>${label}<textarea name="${name}" rows="3">${escapeHtml(value)}</textarea></label>`; }
function repeater(title, key, rows, renderer) { return `<section class="admin-section" data-repeat-section="${key}"><div class="admin-section-heading"><div><div class="eyebrow">${title}</div></div><button type="button" class="button secondary small" data-add-repeat="${key}">${icon('plus')} Añadir</button></div><div class="repeat-list" data-repeat-list="${key}">${rows.map((row, index) => renderer(row, index)).join('')}</div></section>`; }
function repeatItem(key, content) { return `<div class="repeat-item" data-repeat-item="${key}">${content}<button type="button" class="repeat-remove" data-remove-repeat="${key}" title="Quitar">×</button></div>`; }
function editorPage(plant) {
  const isNew = !plant; const p = plant || { commonName: '', guaraniName: '', scientificName: '', family: '', description: '', slug: '', synonyms: [], parts: [], preparations: [], traditionalUses: [], compounds: [], activities: [], evidence: [], references: [], image: {} };
  return `<div class="content-page admin-page"><div class="admin-header"><div><button class="back-link" data-action="navigate:admin">${icon('back')} Volver al panel</button><div class="eyebrow">${isNew ? 'Nuevo perfil' : 'Editar perfil'}</div><h1>${isNew ? 'Añadir planta' : escapeHtml(p.commonName)}</h1><p>Completa solo la información respaldada por fuentes. Los campos marcados con * son obligatorios.</p></div><div class="admin-header-actions">${!isNew ? button('Vista pública', `navigate:plant:${p.slug}`, 'button secondary', 'external') : ''}<button form="plant-editor" class="button primary" type="submit">Guardar perfil</button></div></div><form id="plant-editor" class="plant-editor" data-plant-editor data-plant-id="${isNew ? '' : p.id}"><section class="admin-section"><div class="admin-section-heading"><div><div class="eyebrow">01 · Identificación</div><h2>Datos principales</h2></div></div><div class="form-grid">${input('Nombre común', 'commonName', p.commonName, 'text', true)}${input('Nombre en guaraní', 'guaraniName', p.guaraniName)}${input('Nombre científico', 'scientificName', p.scientificName, 'text', true)}${input('Familia botánica', 'family', p.family)}${input('Identificador web', 'slug', p.slug)}${textarea('Descripción', 'description', p.description)}</div><div class="form-grid compact-grid">${input('Sinónimos (separados por coma)', 'synonyms', p.synonyms.join(', '))}${input('Partes utilizadas (separadas por coma)', 'parts', p.parts.join(', '))}</div></section><section class="admin-section"><div class="eyebrow">Imagen y atribución</div><div class="form-grid">${input('URL de imagen', 'imageUrl', p.image.url)}${input('Pie de imagen', 'imageCaption', p.image.caption)}${input('Crédito / fuente', 'imageCredit', p.image.credit)}${input('Licencia', 'imageLicense', p.image.license)}</div></section>${repeater('02 · Preparaciones', 'preparations', p.preparations, (row) => repeatItem('preparations', `${input('Preparación', 'name', row.name || row)}${input('Notas', 'notes', row.notes || '')}`))}${repeater('03 · Usos tradicionales', 'traditionalUses', p.traditionalUses, (row) => repeatItem('traditionalUses', `${input('Categoría', 'category', row.category)}${textarea('Descripción del uso', 'description', row.description)}${input('Parte involucrada', 'plantPart', row.plantPart)}${input('Preparación tradicional', 'preparation', row.preparation)}${textarea('Notas culturales o contextuales', 'contextNotes', row.contextNotes)}`))}${repeater('04 · Fitoquímica', 'compounds', p.compounds, (row) => repeatItem('compounds', `${input('Nombre del compuesto o grupo', 'name', row.name)}${input('Clase', 'compoundClass', row.compoundClass)}${textarea('Notas', 'notes', row.notes)}<label class="checkbox-line"><input name="qualitativelyIdentified" type="checkbox" ${row.qualitativelyIdentified ? 'checked' : ''}/> Identificado cualitativamente</label><div class="nested-quant"><div class="nested-heading"><strong>Datos cuantitativos</strong><button type="button" class="link-button" data-add-quantity>Añadir valor</button></div><div data-quantity-list>${(row.quantitativeValues || []).map((quantity) => quantityRow(quantity)).join('')}</div></div>`))}${repeater('05 · Actividades biológicas / propiedades', 'activities', p.activities, (row) => repeatItem('activities', `${input('Actividad o propiedad', 'name', row.name)}${textarea('Descripción y contexto', 'description', row.description)}`))}${repeater('06 · Evidencia científica', 'evidence', p.evidence, (row) => repeatItem('evidence', `<label>Tipo de evidencia<select name="evidenceType">${evidenceTypes.map((item) => `<option value="${item.id}" ${item.id === row.evidenceType ? 'selected' : ''}>${item.label}</option>`).join('')}</select></label>${textarea('Notas', 'notes', row.notes)}`))}${repeater('07 · Referencias científicas', 'references', p.references, (row) => repeatItem('references', `${input('Título', 'title', row.title, 'text', true)}${input('Autores', 'authors', row.authors)}${input('Año', 'publicationYear', row.publicationYear, 'number')}${input('Revista o fuente', 'journalOrSource', row.journalOrSource)}${input('DOI', 'doi', row.doi)}${input('URL', 'url', row.url, 'url')}${input('Texto de cita', 'citationText', row.citationText)}${textarea('Notas', 'notes', row.notes)}`))}<div class="editor-footer"><p class="form-message" data-form-message></p><button class="button primary" type="submit">Guardar perfil</button></div></form></div>`;
}
function quantityRow(item = {}) { return `<div class="quantity-row">${input('Valor', 'value', item.value)}${input('Mínimo', 'minimumValue', item.minimumValue)}${input('Máximo', 'maximumValue', item.maximumValue)}${input('Unidad', 'unit', item.unit)}${input('Base', 'basis', item.basis)}${input('Parte / método', 'plantPart', item.plantPart)}${input('Extracción', 'extractionMethod', item.extractionMethod)}${input('Condiciones de muestra', 'sampleConditions', item.sampleConditions)}${input('Notas', 'notes', item.notes)}<button type="button" class="repeat-remove" data-remove-quantity>×</button></div>`; }
function adminDashboard() { const filtered = state.plants.filter((plant) => [plant.commonName, plant.guaraniName, plant.scientificName].join(' ').toLowerCase().includes(state.adminSearch.toLowerCase())); return `<div class="content-page admin-page"><div class="admin-header"><div><div class="eyebrow">Datos editables</div><h1>Panel de administración</h1><p>Gestiona perfiles, evidencia y referencias. Las plantas permanecen visibles aunque estén incompletas.</p></div><div class="admin-header-actions"><button class="button secondary" data-action="admin-logout">Cerrar sesión</button>${button('Añadir planta', 'navigate:admin:edit:new', 'button primary', 'plus')}</div></div><div class="admin-toolbar"><label class="search-box">${icon('search')}<input data-field="admin-search" value="${escapeHtml(state.adminSearch)}" placeholder="Buscar planta…"/></label><span>${filtered.length} de ${state.plants.length} perfiles</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Planta</th><th>Nombre científico</th><th>Estado</th><th>Actualizada</th><th>Acciones</th></tr></thead><tbody>${filtered.map((plant) => `<tr><td><strong>${escapeHtml(plant.commonName)}</strong><small>${escapeHtml(plant.guaraniName || 'Sin nombre guaraní')}</small></td><td><em>${escapeHtml(plant.scientificName)}</em></td><td><span class="completeness ${plant.completeness.complete ? 'complete' : 'incomplete'}">${plant.completeness.complete ? 'Completa' : 'Falta información'}</span>${!plant.completeness.complete ? `<small>${escapeHtml(plant.completeness.missing.join(', '))}</small>` : ''}</td><td>${plant.updatedAt ? new Date(plant.updatedAt).toLocaleDateString('es-PY') : '—'}</td><td class="table-actions"><button data-action="navigate:plant:${plant.slug}">Ver</button><button data-action="navigate:admin:edit:${plant.id}">Editar</button><button class="danger-link" data-action="admin-delete:${plant.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div></div>`; }

function render() {
  const { page, id, sub } = state.route;
  let content;
  if (state.loading) content = '<div class="content-page loading-state">Cargando información desde PostgreSQL…</div>';
  else if (state.error) content = `<div class="content-page"><div class="empty-state"><h3>No se pudo cargar la información</h3><p>${escapeHtml(state.error)}</p><button class="button secondary" data-action="reload">Reintentar</button></div></div>`;
  else if (page === 'admin') content = state.admin ? (id === 'edit' ? editorPage(sub === 'new' ? null : getPlant(sub)) : adminDashboard()) : adminLogin();
  else if (page === 'home') content = homePage(); else if (page === 'plants') content = plantsPage(); else if (page === 'plant') content = plantPage(id); else if (page === 'categories') content = categoriesPage(); else if (page === 'compare') content = comparePage(); else if (page === 'mixture') content = mixturePage(); else content = aboutPage();
  document.querySelector('#app').innerHTML = page === 'admin' && state.admin && id === 'edit' ? shell(content) : shell(content);
  bindEvents();
}

function formValue(row, name) { return row.querySelector(`[name="${name}"]`)?.value?.trim() || ''; }
function collectRepeater(form, key) { return [...form.querySelectorAll(`[data-repeat-item="${key}"]`)].map((row) => Object.fromEntries([...row.querySelectorAll('input, textarea, select')].filter((field) => !field.closest('[data-quantity-list]')).map((field) => [field.name, field.type === 'checkbox' ? field.checked : field.value.trim()]))); }
function collectPlantForm(form) {
  const value = (name) => form.querySelector(`[name="${name}"]`)?.value?.trim() || '';
  const parseList = (name) => value(name).split(',').map((item) => item.trim()).filter(Boolean);
  const compounds = collectRepeater(form, 'compounds').map((item, index) => ({ ...item, qualitativeIdentified: Boolean(item.qualitativelyIdentified), qualitativelyIdentified: Boolean(item.qualitativelyIdentified), quantitativeValues: [...form.querySelectorAll(`[data-repeat-item="compounds"]`)][index] ? [...[...form.querySelectorAll(`[data-repeat-item="compounds"]`)][index].querySelectorAll('[data-quantity-list] .quantity-row')].map((row) => Object.fromEntries([...row.querySelectorAll('input')].map((field) => [field.name, field.value.trim()]))): [] }));
  return { commonName: value('commonName'), guaraniName: value('guaraniName'), scientificName: value('scientificName'), family: value('family'), slug: value('slug'), description: value('description'), synonyms: parseList('synonyms'), parts: parseList('parts'), image: { url: value('imageUrl'), caption: value('imageCaption'), credit: value('imageCredit'), license: value('imageLicense') }, preparations: collectRepeater(form, 'preparations'), traditionalUses: collectRepeater(form, 'traditionalUses'), compounds, activities: collectRepeater(form, 'activities'), evidence: collectRepeater(form, 'evidence').map((item) => ({ ...item, activityIndex: item.activityIndex === '' ? null : Number(item.activityIndex), compoundIndex: item.compoundIndex === '' ? null : Number(item.compoundIndex), traditionalUseIndex: item.traditionalUseIndex === '' ? null : Number(item.traditionalUseIndex), referenceIndex: item.referenceIndex === '' ? null : Number(item.referenceIndex) })), references: collectRepeater(form, 'references') };
}

function bindEvents() {
  document.querySelectorAll('[data-action]').forEach((element) => element.addEventListener('click', async () => {
    const action = element.dataset.action;
    if (action === 'toggle-menu') { state.mobileMenu = !state.mobileMenu; render(); return; }
    if (action === 'reload') { await loadPlants(); return; }
    if (action.startsWith('navigate:')) { const bits = action.split(':'); navigate([bits[1], bits[2], bits[3]].filter(Boolean).join('/')); return; }
    if (action === 'reset-catalog') { state.search = ''; state.filter = 'Todas'; state.sort = 'A–Z'; render(); return; }
    if (action === 'clear-compare') { state.compare = []; render(); return; }
    if (action === 'open-compare-picker') { state.compareOpen = true; render(); document.querySelector('[data-field="add-compare"]')?.focus(); return; }
    if (action.startsWith('add-compare:')) { if (!state.compare.includes(action.split(':')[1]) && state.compare.length < 4) state.compare.push(action.split(':')[1]); render(); return; }
    if (action.startsWith('remove-compare:')) { state.compare = state.compare.filter((id) => id !== action.split(':')[1]); render(); return; }
    if (action.startsWith('add-mixture:')) { const id = action.split(':')[1]; if (!state.mixture.some((item) => item.id === id)) state.mixture.push({ id, amount: 1 }); render(); return; }
    if (action.startsWith('remove-mixture:')) { state.mixture = state.mixture.filter((item) => item.id !== action.split(':')[1]); render(); return; }
    if (action.startsWith('category:')) { state.filter = action.slice(9); navigate('plants'); return; }
    if (action === 'admin-logout') { await apiFetch('/api/admin/logout', { method: 'POST' }); state.admin = false; navigate('home'); return; }
    if (action.startsWith('admin-delete:')) { const plant = getPlant(action.split(':')[1]); if (plant && confirm(`¿Estás seguro de que quieres eliminar “${plant.commonName}”? Esta acción eliminará sus usos, evidencia y referencias.`)) { const response = await apiFetch(`/api/plants/${plant.id}`, { method: 'DELETE' }); if (!response.ok) alert('No se pudo eliminar la planta.'); else await loadPlants(); } }
  }));
  document.querySelectorAll('[data-field="search"]').forEach((input) => input.addEventListener('input', (event) => { state.search = event.target.value; render(); document.querySelector('[data-field="search"]')?.focus(); }));
  document.querySelectorAll('[data-field="admin-search"]').forEach((input) => input.addEventListener('input', (event) => { state.adminSearch = event.target.value; render(); document.querySelector('[data-field="admin-search"]')?.focus(); }));
  document.querySelectorAll('[data-field="filter"]').forEach((input) => input.addEventListener('change', (event) => { state.filter = event.target.value; render(); }));
  document.querySelectorAll('[data-field="sort"]').forEach((input) => input.addEventListener('change', (event) => { state.sort = event.target.value; render(); }));
  document.querySelectorAll('[data-field="add-compare"]').forEach((input) => input.addEventListener('change', (event) => { if (event.target.value) { state.compare.push(event.target.value); state.compareOpen = false; render(); } }));
  document.querySelectorAll('[data-field="add-mixture"]').forEach((input) => input.addEventListener('change', (event) => { if (event.target.value) { state.mixture.push({ id: event.target.value, amount: 1 }); render(); } }));
  document.querySelectorAll('[data-amount]').forEach((input) => input.addEventListener('change', (event) => { const item = state.mixture.find((entry) => entry.id === event.target.dataset.amount); if (item) item.amount = Math.max(0, Number(event.target.value) || 0); }));
  document.querySelector('[data-admin-login]')?.addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const response = await apiFetch('/api/admin/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password: form.password.value }) }); if (response.ok) { state.admin = true; navigate('admin'); } else form.querySelector('[data-form-message]').textContent = (await response.json()).error || 'No se pudo iniciar sesión.'; });
  document.querySelector('[data-plant-editor]')?.addEventListener('submit', submitPlant);
  document.querySelectorAll('[data-add-repeat]').forEach((buttonElement) => buttonElement.addEventListener('click', () => addRepeat(buttonElement.dataset.addRepeat)));
  document.querySelectorAll('[data-remove-repeat]').forEach((buttonElement) => buttonElement.addEventListener('click', () => buttonElement.closest('[data-repeat-item]')?.remove()));
  document.querySelectorAll('[data-add-quantity]').forEach((buttonElement) => buttonElement.addEventListener('click', () => buttonElement.closest('[data-repeat-item]').querySelector('[data-quantity-list]').insertAdjacentHTML('beforeend', quantityRow())));
  document.querySelectorAll('[data-remove-quantity]').forEach((buttonElement) => buttonElement.addEventListener('click', () => buttonElement.closest('.quantity-row')?.remove()));
}

function bindNewRepeatEvents(root) { root.querySelectorAll("[data-remove-repeat]").forEach((buttonElement) => buttonElement.addEventListener("click", () => buttonElement.closest("[data-repeat-item]")?.remove())); root.querySelectorAll("[data-add-quantity]").forEach((buttonElement) => buttonElement.addEventListener("click", () => buttonElement.closest("[data-repeat-item]").querySelector("[data-quantity-list]").insertAdjacentHTML("beforeend", quantityRow()))); root.querySelectorAll("[data-remove-quantity]").forEach((buttonElement) => buttonElement.addEventListener("click", () => buttonElement.closest(".quantity-row")?.remove())); }
function addRepeat(key) { const listElement = document.querySelector(`[data-repeat-list="${key}"]`); if (!listElement) return; const templates = { preparations: repeatItem('preparations', `${input('Preparación', 'name')}${input('Notas', 'notes')}`), traditionalUses: repeatItem('traditionalUses', `${input('Categoría', 'category')}${textarea('Descripción del uso', 'description')}${input('Parte involucrada', 'plantPart')}${input('Preparación tradicional', 'preparation')}${textarea('Notas culturales o contextuales', 'contextNotes')}`), compounds: repeatItem('compounds', `${input('Nombre del compuesto o grupo', 'name')}${input('Clase', 'compoundClass')}${textarea('Notas', 'notes')}<label class="checkbox-line"><input name="qualitativelyIdentified" type="checkbox"/> Identificado cualitativamente</label><div class="nested-quant"><div class="nested-heading"><strong>Datos cuantitativos</strong><button type="button" class="link-button" data-add-quantity>Añadir valor</button></div><div data-quantity-list></div></div>`), activities: repeatItem('activities', `${input('Actividad o propiedad', 'name')}${textarea('Descripción y contexto', 'description')}`), evidence: repeatItem('evidence', `<label>Tipo de evidencia<select name="evidenceType">${evidenceTypes.map((item) => `<option value="${item.id}">${item.label}</option>`).join('')}</select></label>${textarea('Notas', 'notes')}`), references: repeatItem('references', `${input('Título', 'title', '', 'text', true)}${input('Autores', 'authors')}${input('Año', 'publicationYear', '', 'number')}${input('Revista o fuente', 'journalOrSource')}${input('DOI', 'doi')}${input('URL', 'url', '', 'url')}${input('Texto de cita', 'citationText')}${textarea('Notas', 'notes')}`) }; if (templates[key]) { listElement.insertAdjacentHTML('beforeend', templates[key]); bindNewRepeatEvents(listElement); } }
async function submitPlant(event) { event.preventDefault(); const form = event.currentTarget; const message = form.querySelector('[data-form-message]'); message.textContent = 'Guardando…'; const payload = collectPlantForm(form); const id = form.dataset.plantId; const response = await apiFetch(id ? `/api/plants/${id}` : '/api/plants', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); if (!response.ok) { message.textContent = (await response.json()).error || 'No se pudo guardar el perfil.'; return; } await loadPlants(); const saved = await response.json(); state.route = { page: 'admin', id: 'edit', sub: saved.id }; navigate(`admin/edit/${saved.id}`); }
async function loadPlants() { state.loading = true; state.error = ''; render(); try { const response = await apiFetch('/api/plants'); if (!response.ok) throw new Error('La base de datos no respondió correctamente.'); state.plants = await response.json(); state.loading = false; if (!state.compare.length) state.compare = state.plants.slice(0, 2).map((plant) => plant.id); if (!state.mixture.length) state.mixture = state.plants.slice(0, 3).map((plant, index) => ({ id: plant.id, amount: index + 1 })); render(); } catch (error) { state.loading = false; state.error = error.message; render(); } }
async function checkSession() { const response = await apiFetch('/api/session'); state.admin = response.ok && (await response.json()).authenticated; }

await checkSession(); await loadPlants();
